CREATE TABLE ejemplares(id VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, libro_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, UNIQUE(id,libro_id), FOREIGN KEY(libro_id) REFERENCES libros(id) ON DELETE RESTRICT) ENGINE=InnoDB;
ALTER TABLE prestamos DROP INDEX libro_activo, DROP COLUMN libro_activo, ADD COLUMN ejemplar_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, ADD COLUMN ejemplar_activo VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN estado='ACTIVO' THEN ejemplar_id ELSE NULL END) STORED, ADD UNIQUE(ejemplar_activo), ADD FOREIGN KEY(ejemplar_id,libro_id) REFERENCES ejemplares(id,libro_id) ON DELETE RESTRICT;
